const InventoryService={upsert(record){const i=Store.data.products.findIndex(p=>p.id===record.id);if(i<0)Store.data.products.unshift(record);else Store.data.products[i]=record;Store.log(`${i<0?'Added':'Updated'} product: ${record.name}`);Store.save('products')},remove(id){const p=Store.data.products.find(x=>x.id===id);if(!p)return;Store.data.products=Store.data.products.filter(x=>x.id!==id);Store.log(`Deleted product: ${p.name}`);Store.save('products')},update(id,changes){const p=Store.data.products.find(x=>x.id===id);if(p)this.upsert({...p,...changes})}};
const SyncEngine={init(){if('BroadcastChannel'in window){try{Store.channel=new BroadcastChannel(CONFIG.channel);Store.channel.onmessage=e=>this.receive(e.data)}catch{}}window.addEventListener('storage',e=>{if(!e.key?.startsWith(CONFIG.prefix+'.')||!e.newValue)return;const name=Object.keys(keys).find(k=>`${CONFIG.prefix}.${keys[k]}`===e.key);if(name&&Store.refresh(name,e.newValue)){Store.revision++;this.render(name)}});window.addEventListener('we:change',e=>this.render(e.detail.name));this.status()},receive(m){if(!m||m.origin===tabId||!m.id||Store.seen.has(m.id))return;Store.seen.add(m.id);if(Store.seen.size>150)Store.seen.delete(Store.seen.values().next().value);const key=keys[m.name];if(!key||!Array.isArray(m.data)&&m.name!=='settings')return;Store.data[m.name]=m.name==='settings'?{...defaults,...m.data,hours:{...defaults.hours,...(m.data.hours||{})}}:m.data;try{localStorage.setItem(`${CONFIG.prefix}.${key}`,JSON.stringify(Store.data[m.name]))}catch{}Store.revision++;this.render(m.name,true)},render(name,remote=false){UI.renderAll();if(remote)Toast.show(`${name[0].toUpperCase()+name.slice(1)} updated in another tab`,'success')},status(){const on=Store.data.settings.broadcast;for(const el of [document.querySelector('#liveSync'),document.querySelector('#adminSync')])if(el){el.classList.toggle('off',!on);el.lastChild.textContent=on?' Live sync ready':' Local updates only'}}};
const TechMatch={recommend(use,budget,priority){const map={study:['Laptops & PCs','Accessories'],work:['Laptops & PCs','Accessories'],gaming:['Laptops & PCs'],mobile:['Mobile & Tablets','Accessories'],home:['Home Appliances','Accessories']};let pool=products().filter(p=>map[use].includes(p.category)&&p.price<=budget&&p.stock>0);const words={value:['budget','everyday','value'],performance:['gaming','performance','pro'],portable:['portable','phone','tablet','laptop'],reliable:['reliable','everyday','family']}[priority];pool.sort((a,b)=>{const score=p=>(p.featured?2:0)+(stockState(p)==='in'?1:0)+(words.some(w=>`${p.name} ${p.description} ${p.keywords}`.toLowerCase().includes(w))?2:0)+(p.rating||0)/5;return score(b)-score(a)});return pool.slice(0,3).map(p=>({p,reason:`Fits your ${use==='study'?'study and everyday':use} needs, stays within ${money(budget)}, and supports your ${priority} priority. ${stockText(p)}.`}))}};
const TechCare={guide(category){const tips={'Laptops & PCs':['Keep vents clear and install system updates regularly.','Use a padded sleeve for travel and avoid extreme heat.'],'Mobile & Tablets':['Use a reputable charger and keep the device dry.','Back up important data and install security updates.'],'Home Appliances':['Leave ventilation space and follow the manufacturer’s cleaning guidance.','If you notice unusual heat, smell, or noise, stop use and seek qualified support.'],'Accessories':['Store cables without tight bends and keep connectors clean and dry.','Check device compatibility before connecting power accessories.']}[category]||[];const services=Store.data.services.filter(s=>s.published&&[category,'General support','Consultation'].some(k=>`${s.type} ${s.name}`.toLowerCase().includes(k.toLowerCase())||category==='Laptops & PCs'&&/computer/i.test(s.type)||category==='Mobile & Tablets'&&/mobile/i.test(s.type)||category==='Home Appliances'&&/appliance/i.test(s.type)));return {tips,services}}};
