function showAdmin(){document.querySelector('#storeView').classList.add('hidden');document.querySelector('#adminView').classList.remove('hidden');Admin.render();window.scrollTo(0,0)}
function setFilter(key,value){UI.filters[key]=value;UI.renderProducts()}
document.querySelector('#pinForm').onsubmit=e=>{e.preventDefault();if(document.querySelector('#pinInput').value===Store.data.settings.pin){closeDialog('pinDialog');document.querySelector('#pinInput').value='';showAdmin()}else Toast.show('That PIN did not match. Try again.','error')};
