['adminEntry','footerAdmin'].forEach(id=>document.getElementById(id).onclick=requestAdmin);document.querySelector('#exitAdmin').onclick=()=>{document.querySelector('#adminView').classList.add('hidden');document.querySelector('#storeView').classList.remove('hidden');window.scrollTo(0,0)};document.querySelector('#directionsBtn').onclick=()=>Customer.directions();
