function clearFilters(){UI.filters={q:'',category:'',availability:'',min:'',max:'',featured:false,sort:'featured'};document.querySelector('#navSearch').value='';document.querySelector('#catalogSearch').value='';document.querySelector('#priceSlider').value=document.querySelector('#priceSlider').max;UI.syncControls();UI.renderProducts()}document.querySelector('#clearFilters').onclick=clearFilters;document.querySelector('#clearFiltersTop').onclick=clearFilters;document.querySelector('#productGrid').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(action==='detail')Customer.open(id);if(action==='wish')Customer.toggle('wishlist',id);if(action==='compare')Customer.toggle('compare',id);if(action==='whatsapp')Customer.whatsapp(id);if(action==='restock')Customer.inquiry('Restock request',id);if(action==='clear')clearFilters()});document.querySelector('#serviceGrid').onclick=e=>{const b=e.target.closest('[data-action="serviceInquiry"]');if(b)Customer.inquiry('Repair service',b.dataset.id)};
document.querySelector('#wishNav').onclick=()=>Customer.wishlist();document.querySelector('#compareNav').onclick=()=>Customer.showCompare();document.querySelector('#directionsBtn').onclick=()=>Customer.directions();document.querySelector('#repairInquiryBtn').onclick=()=>Customer.inquiry('Repair service');
document.querySelector('#runMatch').onclick=()=>{const use=document.querySelector('#matchUse').value,budget=+document.querySelector('#matchBudget').value,priority=document.querySelector('#matchPriority').value,res=TechMatch.recommend(use,budget,priority),host=document.querySelector('#matchResult');host.innerHTML=res.length?`<h3>Your matches</h3>`+res.map(({p,reason})=>`<div class="panel" style="margin-top:9px"><strong>${escapeHTML(p.name)}</strong> · ${money(p.price)}<p>${escapeHTML(reason)}</p><button class="btn small primary" data-action="detail" data-id="${escapeHTML(p.id)}">View details</button></div>`).join(''):'<div class="banner">No in-stock matches in this sample catalog. Try a larger budget or different use.</div>'};document.querySelector('#matchResult').onclick=e=>{const b=e.target.closest('[data-action="detail"]');if(b)Customer.open(b.dataset.id)};
document.querySelector('#passportBtn').onclick=()=>{const category=document.querySelector('#passportDevice').value,{tips,services}=TechCare.guide(category);document.querySelector('#passportResult').innerHTML=`<div style="margin-top:16px"><h3>Care notes</h3><ul>${tips.map(t=>`<li>${escapeHTML(t)}</li>`).join('')}</ul><h3>Related support in this demo</h3>${services.length?services.map(s=>`<p><strong>${escapeHTML(s.name)}</strong> · ${money(s.price)}</p>`).join(''):'<p>No directly related published service is listed; general support is available.</p>'}</div>`};
document.querySelector('#inquiryForm').onsubmit=e=>{e.preventDefault();const itemId=document.querySelector('#inqProduct').value,item=[...Store.data.products,...Store.data.services].find(x=>x.id===itemId);const inquiry={id:uid(),name:document.querySelector('#inqName').value.trim(),contact:document.querySelector('#inqContact').value.trim(),type:document.querySelector('#inqType').value,item:item?.name||'',message:document.querySelector('#inqMessage').value.trim(),status:'New',time:new Date().toISOString()};if(!inquiry.name||!inquiry.contact||!inquiry.message){Toast.show('Complete all required fields.','error');return}Store.data.inquiries.unshift(inquiry);Store.log(`New ${inquiry.type.toLowerCase()} from ${inquiry.name}`);Store.save('inquiries');Store.save('activity');e.currentTarget.reset();closeDialog('inquiryDialog');Toast.show('Your demo inquiry was saved. The team can review it in Admin.');UI.renderAll()};
document.querySelector('#adminView').addEventListener('click',e=>{const tab=e.target.closest('[data-admin-tab]');if(tab){document.querySelectorAll('[data-admin-tab]').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('.adminsection').forEach(x=>x.classList.toggle('active',x.id===`admin-${tab.dataset.adminTab}`))}});
document.querySelector('#addProduct').onclick=()=>Admin.productForm();document.querySelector('#addService').onclick=()=>Admin.serviceForm();document.querySelector('#adminProductSearch').oninput=()=>Admin.products();
document.querySelector('#productTable').addEventListener('change',e=>{const el=e.target.closest('[data-quick]');if(!el)return;const val=+el.value;if(!Number.isFinite(val)||val<0||el.dataset.quick==='price'&&val===0||el.dataset.quick==='stock'&&!Number.isInteger(val)){Toast.show('Enter a valid nonnegative amount.','error');Admin.products();return}InventoryService.update(el.dataset.id,{[el.dataset.quick]:val});Toast.show('Quick edit saved')});
document.querySelector('#adminView').addEventListener('click',e=>{const b=e.target.closest('[data-admin-action]');if(!b)return;const {adminAction:a,id}=b.dataset;if(a==='editProduct')Admin.productForm(Store.data.products.find(p=>p.id===id));if(a==='deleteProduct'&&confirm('Delete this product from the local demo catalog?'))InventoryService.remove(id);if(a==='feature')InventoryService.update(id,{featured:!Store.data.products.find(p=>p.id===id).featured});if(a==='publishProduct')InventoryService.update(id,{published:!Store.data.products.find(p=>p.id===id).published});if(a==='editService')Admin.serviceForm(Store.data.services.find(s=>s.id===id));if(a==='publishService'){const s=Store.data.services.find(s=>s.id===id);s.published=!s.published;Store.log(`${s.published?'Published':'Unpublished'} service: ${s.name}`);Store.save('services')}if(a==='deleteService'&&confirm('Delete this service from the local demo catalog?')){Store.data.services=Store.data.services.filter(s=>s.id!==id);Store.log('Deleted repair service');Store.save('services')}if(a==='deleteInquiry'&&confirm('Delete this local demonstration inquiry?')){Store.data.inquiries=Store.data.inquiries.filter(i=>i.id!==id);Store.log('Deleted customer inquiry');Store.save('inquiries');Store.save('activity')}});
document.querySelector('#inquiryStatus').onchange=()=>Admin.inquiries();document.querySelector('#inquiryTable').onchange=e=>{const sel=e.target.closest('[data-inq-status]');if(!sel)return;const i=Store.data.inquiries.find(x=>x.id===sel.dataset.inqStatus);if(i){i.status=sel.value;Store.log(`Inquiry status changed to ${i.status}`);Store.save('inquiries');Store.save('activity')}};
document.querySelector('#saveSettings').onclick=()=>{const form=document.querySelector('#settingsForm');if(!form.reportValidity())return;const f=new FormData(form),s={...Store.data.settings};for(const k of ['storeName','currency','locale','email','phone','whatsapp','address','latitude','longitude','servicesDefault','pin'])s[k]=String(f.get(k)||'').trim();s.currency=s.currency.toUpperCase();s.lowStock=+f.get('lowStock');s.activityLimit=+f.get('activityLimit');s.broadcast=form.elements.broadcast.checked;if(s.lowStock<1||s.activityLimit<5||s.pin.length<4){Toast.show('Check threshold, activity limit, and PIN values.','error');return}s.hours={};for(const [k] of Object.entries({mon:1,tue:1,wed:1,thu:1,fri:1,sat:1,sun:1})){const a=form.elements[`${k}Open`].value,b=form.elements[`${k}Close`].value;s.hours[k]=form.elements[`${k}Closed`].checked?null:a&&b?[a,b]:null}Store.data.settings=s;Store.log('Updated store settings');Store.save('settings');Store.save('activity');UI.renderAll();Toast.show('Settings saved')};
document.querySelector('#exportData').onclick=()=>{const data={schema:CONFIG.schema,...Store.data};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='world-electronics-demo.json';a.click();URL.revokeObjectURL(url);Toast.show('Demo data exported')};
document.querySelector('#importFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{const x=JSON.parse(await file.text());if(x.schema!==CONFIG.schema||!Array.isArray(x.products)||!Array.isArray(x.services)||!Array.isArray(x.inquiries)||!x.settings||!Array.isArray(x.activity)||!x.preferences)throw Error('Unsupported or incomplete data schema');const unique=a=>a.every((v,i)=>v&&typeof v.id==='string'&&a.findIndex(y=>y.id===v.id)===i);if(!unique(x.products)||!unique(x.services)||x.products.some(p=>typeof p.price!=='number'||p.price<0||!Number.isInteger(p.stock)||p.stock<0))throw Error('Records contain invalid IDs, prices, or stock values');if(!confirm('Import will replace the current local demo records. Continue?'))return;Store.data={products:x.products,services:x.services,inquiries:x.inquiries,settings:{...defaults,...x.settings,hours:{...defaults.hours,...x.settings.hours}},activity:x.activity,preferences:{wishlist:[],compare:[],...x.preferences}};Store.log('Imported validated demo data');Store.saveAll();UI.renderAll();Toast.show('Data imported successfully')}catch(err){Toast.show(`Import rejected: ${err.message}`,'error')}finally{e.target.value=''}};
document.querySelector('#resetData').onclick=()=>{if(confirm('Reset the complete local demo to its original products, services, and settings? This replaces current records in this browser.')){Store.reset();Store.saveAll();UI.renderAll();Toast.show('Demo data reset')}};
document.querySelector('#settingsForm').addEventListener('submit',e=>e.preventDefault());
document.querySelector('#toastStack');document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeDialog(b.dataset.close));document.querySelectorAll('dialog').forEach(d=>{d.addEventListener('click',e=>{if(e.target===d)d.close()});d.addEventListener('cancel',()=>{})});
document.querySelector('#wishContent').onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='wish'){Customer.toggle('wishlist',b.dataset.id);Customer.wishlist()}else if(b.dataset.action==='detail')Customer.open(b.dataset.id)};document.querySelector('#compareContent').onclick=e=>{if(e.target.closest('[data-action="clearCompare"]')){Store.data.preferences.compare=[];Store.save('preferences',false);UI.renderCounts();Customer.showCompare()}};
document.querySelector('#menuToggle').onclick=()=>{const nav=document.querySelector('.links');const shown=nav.style.display==='flex';nav.style.cssText=shown?'':'display:flex;position:absolute;top:64px;left:0;right:0;padding:14px 20px;background:white;flex-direction:column;align-items:flex-start;border-bottom:1px solid #e2e8f0'};
window.addEventListener('scroll',()=>document.querySelector('#nav').classList.toggle('scrolled',scrollY>12),{passive:true});setInterval(()=>UI.updateHours(),30000);
/* Boot: initialize storage once, attach sync, render. */
Store.load();SyncEngine.init();UI.renderAll();UI.syncControls();
